export function normalizeL2Name(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]/g, "");
}

export function getL2IconPath(nameOrSlug: string): string | null {
  if (!nameOrSlug) return null;
  const raw = nameOrSlug.trim();
  const normalized = normalizeL2Name(raw);
  
  if (L2_ICON_MAP[normalized]) {
    return L2_ICON_MAP[normalized];
  }
  if (L2_ICON_MAP[raw]) {
    return L2_ICON_MAP[raw];
  }
  if (L2_ICON_MAP[raw.toLowerCase()]) {
    return L2_ICON_MAP[raw.toLowerCase()];
  }
  return null;
}
